<script setup lang="ts">
import { PARTNER_AGENCIES, SERVICE_CATEGORIES } from '@/utils/caseOptions';
import { computed, ref } from 'vue';
import { Head, Link, usePage } from '@inertiajs/vue3';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import PlanningForm from '@/Components/PlanningForm.vue';
import { useConferenceWorkspace } from '@/composables/useConferenceWorkspace';
import { manilaInputToUtc, philippineTimestamp, storedUtcToManilaInput } from '@/utils/philippineTime';
import type { PlanningData, PlanningField } from '@/types/planning';
import type { ConferenceSummary } from '@/types/conferences';
import type { PageProps } from '@/types';

const props=defineProps<{caseId:number;caseNumber:string;caseStatus:string;conferences:ConferenceSummary[]}>();
const page=usePage<PageProps>();
const {index,detail,selectedId,busy,loaded,refreshRequired,disabled,error,message,errors,errorSummary,failedKey,forms,dirtyKeys,form,reset,load,save,showError}=useConferenceWorkspace(props.caseId);
const canCreate=computed(()=>page.props.auth.permissions.includes('conferences.manage') && (index.value.caseStatus??props.caseStatus)!=='CLOSED');
const record=computed(()=>detail.value?.conference);
const permitted=(name:string)=>Boolean(detail.value?.allowed_actions[name]);
const view=ref('record'),showCreate=ref(false);
const activities=[{key:'record',label:'Conference record'},{key:'attendance',label:'Attendance'},{key:'decisions',label:'Decisions & actions'},{key:'review',label:'Review & history'}];
const human=(value:string|null|undefined)=>value?value.replaceAll('_',' '):'Not recorded';
const field=(key:string,label:string,kind:PlanningField['kind']='text',required=false,max=255,wide=false):PlanningField=>({key,label,kind,required,max,wide});
const options=(values:string[])=>values.map(value=>({value,label:human(value)}));
const select=(key:string,label:string,values:{value:string|number|null;label:string}[]):PlanningField=>({key,label,kind:'select',options:values});
const key=(name:string)=>name==='create'?'create':String(selectedId.value)+':'+name;
function bind(name:string,defaults:()=>PlanningData){return computed({get:()=>form(key(name),defaults()),set:value=>{forms[key(name)]=value;}});}
const creationDefaults=()=>({conference_type:'initial',other_type_reason:'',scheduled_at:'',venue_mode:'',facilitator_name:'',recorder_name:'',purpose:''});
const createForm=bind('create',creationDefaults);
const creationFields:PlanningField[]=[select('conference_type','Conference type',options(['initial','emergency_safety','case_planning','progress_review','family','mdt','placement_review','transfer_handover','reintegration','pre_closure','other'])),field('other_type_reason','Reason for Other type','text',false,500),field('scheduled_at','Scheduled time (Philippine time)','datetime-local'),field('venue_mode','Venue / mode','text',false,100),field('facilitator_name','Facilitator','text',false,180),field('recorder_name','Recorder','text',false,180),field('purpose','Purpose','textarea',false,5000,true)];
const recordDefaults=():PlanningData=>({case_updates:record.value?.case_updates??'',key_issues:record.value?.key_issues??'',family_perspective:record.value?.family_perspective??'',professional_observations:record.value?.professional_observations??'',child_participation_status:record.value?.child_participation_status??null,child_participation_record_id:record.value?.child_participation_record_id??null,risk_assessment_id:record.value?.risk_assessment_id??null,next_review_at:storedUtcToManilaInput(record.value?.next_review_at),confidentiality:record.value?.confidentiality??'casework'});
const recordForm=bind('record',recordDefaults);
const recordFields=computed<PlanningField[]>(()=>[field('case_updates','Case updates','textarea',false,5000,true),field('key_issues','Key issues','textarea',false,5000,true),field('family_perspective','Family perspective','textarea',false,5000,true),field('professional_observations','Professional observations','textarea',false,5000,true),select('child_participation_status','Child participation status',[{value:null,label:'Not recorded'},...options(['direct','previous_views_presented','deferred','not_appropriate','not_participating'])]),select('child_participation_record_id','Finalized participation reference',[{value:null,label:'No reference'},...index.value.participationReferences.map(item=>({value:item.id,label:'Participation #'+item.id+' - version '+item.version}))]),select('risk_assessment_id','Finalized risk assessment reference',[{value:null,label:'No reference'},...index.value.riskReferences.map(item=>({value:item.id,label:'Assessment #'+item.id+' - '+philippineTimestamp(item.assessed_at)}))]),field('next_review_at','Next review (Philippine time)','datetime-local'),select('confidentiality','Recorded confidentiality',options(['casework','restricted']))]);
const participantDefaults=()=>({name:'',professional_role:'',organization:'',attendance_status:'invited',participation_mode:'',conference_role:''});
const participantForm=bind('participant',participantDefaults);
const participantFields:PlanningField[]=[field('name','Participant name','text',true,180),field('professional_role','Professional / family role','text',false,140),field('organization','Organization / office','text',false,180),select('attendance_status','Attendance status',options(['invited','attended','declined','absent'])),field('participation_mode','Participation mode','text',false,60),field('conference_role','Conference role','text',false,80)];
const decisionDefaults=()=>({decision_type:'decision',statement:''});
const decisionForm=bind('decision',decisionDefaults);
const decisionFields:PlanningField[]=[select('decision_type','Record kind',options(['decision','recommendation'])),field('statement','Decision or recommendation','textarea',true,5000,true)];
const actionDefaults=()=>({action:'',category:'',responsible_office:'',target_at:'',priority:'normal',source:''});
const actionForm=bind('action',actionDefaults);
const actionFields=computed<PlanningField[]>(()=>[field('action','Agreed action','textarea',true,5000,true),{...field('category','Action category','text',false,100),kind:'choice',choices:SERVICE_CATEGORIES},{...field('responsible_office','Responsible office','text',false,180),kind:'choice',choices:PARTNER_AGENCIES},field('target_at','Recorded target (Philippine time)','datetime-local'),select('priority','Action priority',options(['low','normal','high','urgent'])),select('source','Existing operational source',[{value:'',label:'No linked source'},...Object.entries(index.value.sources).flatMap(([type,items])=>items.map(item=>({value:type+':'+item.id,label:human(type)+' #'+item.id+' - '+(item.title||item.service_category||'Recorded source')})))])]);
const reviewForm=bind('review',()=>({comments:''}));
const rescheduleDefaults=()=>({scheduled_at:'',reason:''});const rescheduleForm=bind('reschedule',rescheduleDefaults);
const rescheduleFields:PlanningField[]=[field('scheduled_at','New schedule (Philippine time)','datetime-local',true),field('reason','Rescheduling reason','textarea',true,2000,true)];
const addendumDefaults=()=>({reason:'',purpose:''});const addendumForm=bind('addendum',addendumDefaults);
const addendumFields:PlanningField[]=[field('reason','Addendum reason','textarea',true,2000,true),field('purpose','Addendum purpose','textarea',false,5000,true)];
const errorsFor=(name:string)=>failedKey.value===key(name)?errors.value:{};
function discardCreation(){if(!busy.value&&window.confirm('Discard the unfinished new-conference form? Review saved records first if a previous response was interrupted.')){reset('create',creationDefaults());showCreate.value=false;}}
function withTimes(body:PlanningData,fields:string[]):PlanningData{const result={...body};for(const name of fields)result[name]=manilaInputToUtc(String(body[name]??''));return result;}
async function create(){const ok=await save({method:'post',url:route('cases.conferences.store',props.caseId),body:withTimes(createForm.value,['scheduled_at']),key:'create',defaults:creationDefaults(),selectCreated:true,success:'Conference draft created.'});if(ok){showCreate.value=false;view.value='record';}}
async function write(name:string,endpoint:string,body:PlanningData,defaults:PlanningData,method:'post'|'patch'='post',selectCreated=false){if(!selectedId.value)return;await save({method,url:route(endpoint,[props.caseId,selectedId.value]),body,key:key(name),defaults,selectCreated,success:name==='addendum'?'Linked addendum draft created.':'Conference record saved.'});}
const saveRecord=()=>write('record','cases.conferences.update',withTimes(recordForm.value,['next_review_at']),{...recordForm.value},'patch');
const saveParticipant=()=>write('participant','cases.conferences.participants.store',participantForm.value,participantDefaults());
const saveDecision=()=>write('decision','cases.conferences.decisions.store',decisionForm.value,decisionDefaults());
function saveAction(){const body=withTimes(actionForm.value,['target_at']);const [type,id]=String(body.source??'').split(':');delete body.source;body.source_type=type||null;body.source_id=id?Number(id):null;return write('action','cases.conferences.actions.store',body,actionDefaults());}
async function reschedule(){if(disabled.value||!selectedId.value||!await readyForStateChange('reschedule'))return;await write('reschedule','cases.conferences.reschedule',withTimes(rescheduleForm.value,['scheduled_at']),rescheduleDefaults());}
const addendum=()=>write('addendum','cases.conferences.addendum',addendumForm.value,addendumDefaults(),'post',true);
async function readyForStateChange(ignore:string):Promise<boolean>{
 const unfinished=dirtyKeys.value.filter(name=>name.startsWith(String(selectedId.value)+':')&&name!==key(ignore));
 if(unfinished.length){await showError('Save the unfinished conference entries before changing its workflow state.');return false;}
 return true;
}
async function transition(status:string){
 if(disabled.value||!selectedId.value||!await readyForStateChange('review'))return;
 if(!window.confirm('Confirm conference status change to '+human(status)+'?'))return;
 await write('review','cases.conferences.transition',{status,comments:reviewForm.value.comments??''},{comments:''},'patch');
}
function choose(value:string){const id=Number(value);if(Number.isInteger(id)&&id>0)void load(id);}
const readback=computed(()=>[['Case updates',record.value?.case_updates],['Key issues',record.value?.key_issues],['Family perspective',record.value?.family_perspective],['Professional observations',record.value?.professional_observations],['Child participation status',human(record.value?.child_participation_status)],['Participation reference',record.value?.child_participation_record_id?'#'+record.value.child_participation_record_id:null],['Risk assessment reference',record.value?.risk_assessment_id?'#'+record.value.risk_assessment_id:null],['Next review',philippineTimestamp(record.value?.next_review_at)],['Recorded confidentiality',human(record.value?.confidentiality)]]);
</script>

<template>
 <Head title="Case conferences"/><AuthenticatedLayout><section class="mx-auto w-full max-w-[1440px] space-y-5">
  <header class="rounded-lg border border-brand-700 bg-brand-800 p-4 text-white sm:p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-semibold tracking-wide text-brand-100">{{caseNumber}} - formal multidisciplinary record</p><h1 class="mt-1 text-2xl font-semibold">Case conferences</h1><p class="mt-2 max-w-3xl text-sm leading-6 text-brand-50">Record attendance, professional discussion, decisions and follow-up actions.</p></div><div class="flex flex-wrap gap-2"><Link :href="route('cases.show',caseId)" class="ui-button text-brand-900">Back to case</Link><button type="button" class="ui-button text-brand-900" :disabled="busy" @click="load()">Refresh</button><button v-if="canCreate" type="button" class="ui-button text-brand-900" :disabled="disabled" :aria-expanded="showCreate" @click="showCreate=!showCreate">New conference</button></div></div></header>
  <p class="rounded-md border border-sky-200 bg-sky-50 p-3 text-xs leading-5 text-sky-950">Online workspace. Attendance never grants system access. Referenced child participation and health narratives stay in their source modules. All times shown use Philippine time (Asia/Manila).</p>
  <div v-if="error" ref="errorSummary" role="alert" tabindex="-1" class="rounded-md border border-rose-300 bg-rose-50 p-4 text-sm text-rose-900"><p>{{error}}</p><ul v-if="Object.keys(errors).length" class="mt-2 list-inside list-disc"><li v-for="(value,name) in errors" :key="name">{{value}}</li></ul></div>
  <p v-if="message" role="status" class="rounded-md border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-900">{{message}}</p><p v-if="busy" role="status" class="text-sm text-slate-600">Updating conference records...</p><p v-if="dirtyKeys.length" class="rounded-md border border-amber-300 bg-kalinga-warm p-3 text-sm text-amber-950">Unfinished work is retained on this page for each conference. Save online before closing; cancel navigation to keep working.</p>
  <button v-if="dirtyKeys.includes('create')" type="button" class="ui-button" :disabled="busy" @click="discardCreation">Discard unfinished new conference</button>
  <PlanningForm v-if="canCreate&&(showCreate||!index.conferences.length)" id="conference-create" v-model="createForm" title="Schedule conference" description="Create a draft for this case. Include a recorded schedule when known." :fields="creationFields" :busy="disabled" :errors="errorsFor('create')" submit-label="Create draft" @submit="create"/>
  <p v-if="loaded&&!index.conferences.length" class="ui-panel p-5 text-sm text-slate-600">No conferences recorded for this case.</p>
  <div v-if="index.conferences.length" class="grid items-start gap-5 lg:grid-cols-[14rem_minmax(0,1fr)]">
   <aside class="hidden rounded-lg border border-brand-200 bg-kalinga-lavender p-3 lg:block"><h2 class="text-sm font-semibold text-brand-900">Conference records</h2><nav aria-label="Conference records" class="mt-3 space-y-2"><button v-for="item in index.conferences" :key="item.id" type="button" class="min-h-11 w-full rounded-md border p-3 text-left text-sm" :class="selectedId===item.id?'border-brand-800 bg-brand-800 text-white':'border-brand-200 bg-white text-slate-800'" :disabled="busy" :aria-current="selectedId===item.id?'page':undefined" @click="load(item.id)"><span class="block font-semibold">#{{item.id}} - {{human(item.conference_type)}}</span><span class="mt-1 block text-xs">{{human(item.status)}} - {{philippineTimestamp(item.scheduled_at)}}</span></button></nav></aside>
   <div class="min-w-0 space-y-4"><label class="block text-sm font-medium lg:hidden">Conference record<select class="ui-field mt-1" :value="selectedId" :disabled="busy" @change="choose(($event.target as HTMLSelectElement).value)"><option v-for="item in index.conferences" :key="item.id" :value="item.id">#{{item.id}} - {{human(item.conference_type)}} - {{human(item.status)}}</option></select></label>
    <article v-if="detail&&record" id="conference-workspace" class="min-w-0 space-y-4">
     <header class="ui-panel p-4"><h2 class="text-lg font-semibold text-brand-900">Conference #{{record.id}} - {{human(record.status)}}</h2><p class="mt-1 text-sm text-slate-700">{{human(record.conference_type)}} - {{philippineTimestamp(record.scheduled_at)}}</p><p v-if="record.purpose" class="mt-3 whitespace-pre-wrap break-words text-sm leading-6">{{record.purpose}}</p><dl v-if="record.venue_mode||record.facilitator_name||record.recorder_name" class="mt-3 grid gap-3 text-xs text-slate-700 sm:grid-cols-3"><div v-if="record.venue_mode"><dt class="font-semibold">Venue / mode</dt><dd class="mt-1 break-words">{{record.venue_mode||'Not recorded'}}</dd></div><div v-if="record.facilitator_name"><dt class="font-semibold">Facilitator</dt><dd class="mt-1 break-words">{{record.facilitator_name||'Not recorded'}}</dd></div><div v-if="record.recorder_name"><dt class="font-semibold">Recorder</dt><dd class="mt-1 break-words">{{record.recorder_name||'Not recorded'}}</dd></div></dl><p v-else class="mt-3 text-xs leading-5 text-slate-600">Venue, facilitator and recorder not recorded.</p><p v-if="record.previous_conference_id" class="mt-3 rounded border border-amber-300 bg-kalinga-warm p-2 text-sm text-amber-950">Linked addendum to conference #{{record.previous_conference_id}} - {{record.addendum_reason}}</p></header>
     <label class="block md:hidden"><span class="sr-only">Conference activity</span><select v-model="view" class="ui-field border-brand-300 bg-brand-50 font-semibold text-brand-900"><option v-for="item in activities" :key="item.key" :value="item.key">{{item.label}}</option></select></label><nav aria-label="Conference activities" class="hidden gap-1 rounded-lg border border-brand-200 bg-brand-100 p-1 md:grid md:grid-cols-2 xl:grid-cols-4"><button v-for="item in activities" :key="item.key" type="button" class="min-h-11 rounded-md px-3 py-2 text-sm font-semibold" :class="view===item.key?'bg-brand-800 text-white':'text-brand-900'" :aria-current="view===item.key?'page':undefined" @click="view=item.key">{{item.label}}</button></nav>
     <template v-if="view==='record'"><PlanningForm v-if="permitted('edit_draft')" id="conference-record" v-model="recordForm" title="Professional conference record" description="Save the discussion before submitting for independent review. Reference existing assessments without copying their restricted narratives." :fields="recordFields" :busy="disabled" :errors="errorsFor('record')" submit-label="Save conference record" @submit="saveRecord"/><section v-else class="ui-panel p-4"><h3 class="ui-section-title">Professional conference record</h3><dl class="mt-4 space-y-4 text-sm"><div v-for="[label,value] in readback" :key="label||''"><dt class="font-semibold">{{label}}</dt><dd class="mt-1 whitespace-pre-wrap break-words text-slate-700">{{value||'Not recorded'}}</dd></div></dl></section></template>
     <section v-else-if="view==='attendance'" class="space-y-4"><PlanningForm v-if="permitted('edit_draft')" id="conference-participant" v-model="participantForm" title="Add participant" description="Attendance metadata only. This does not grant case access or chat membership." :fields="participantFields" :busy="disabled" :errors="errorsFor('participant')" submit-label="Record participant" @submit="saveParticipant"/><div class="ui-panel overflow-hidden"><header class="ui-panel-header bg-brand-50"><h3 class="ui-section-title">Attendance records</h3><span class="text-xs text-slate-600">{{detail.participants.length}}</span></header><div class="divide-y divide-slate-200"><article v-for="item in detail.participants" :key="item.id" class="space-y-2 p-4 text-sm"><h4 class="break-words font-semibold">{{item.name}}</h4><p class="break-words">{{[item.professional_role,item.organization].filter(Boolean).join(' - ')}}</p><p>{{human(item.attendance_status)}}<span v-if="item.participation_mode"> - {{item.participation_mode}}</span></p><p v-if="item.conference_role" class="break-words">Conference role: {{item.conference_role}}</p></article></div><p v-if="!detail.participants.length" class="ui-muted p-4">No participants recorded.</p></div></section>
     <section v-else-if="view==='decisions'" class="space-y-4"><div class="grid items-start gap-4 xl:grid-cols-2"><PlanningForm v-if="permitted('edit_draft')" id="conference-decision" v-model="decisionForm" title="Decision or recommendation" description="Record the actual agreement and distinguish recommendations." :fields="decisionFields" :busy="disabled" :errors="errorsFor('decision')" submit-label="Record decision" @submit="saveDecision"/><PlanningForm v-if="permitted('edit_draft')" id="conference-action" v-model="actionForm" title="Agreed follow-up action" description="Linked operational records own execution status. Recording an agreement does not complete its source task or referral." :fields="actionFields" :busy="disabled" :errors="errorsFor('action')" submit-label="Record action" @submit="saveAction"/></div><section class="ui-panel p-4"><h3 class="ui-section-title">Recorded decisions and recommendations</h3><article v-for="item in detail.decisions" :key="item.id" class="mt-4 border-t border-slate-200 pt-3 text-sm"><h4 class="font-semibold text-brand-900">{{human(item.decision_type)}}</h4><p class="mt-2 whitespace-pre-wrap break-words leading-6">{{item.statement}}</p></article><p v-if="!detail.decisions.length" class="ui-muted mt-3">No decisions or recommendations recorded.</p></section><section class="ui-panel p-4"><h3 class="ui-section-title">Recorded follow-up actions</h3><article v-for="item in detail.actions" :key="item.id" class="mt-4 space-y-2 rounded-md border border-sky-200 bg-sky-50 p-3 text-sm"><h4 class="whitespace-pre-wrap break-words font-semibold">{{item.action}}</h4><p v-if="item.responsible_office" class="break-words">Responsible office: {{item.responsible_office}}</p><p>{{human(item.priority)}} priority - target {{philippineTimestamp(item.target_at)}}</p><p v-if="item.source_type">Linked {{human(item.source_type)}} #{{item.source_id}} - {{item.operational_status?human(item.operational_status):'Source status unavailable'}}</p><p v-else>Conference action status: {{human(item.local_status)}}</p><p v-if="item.outcome_remarks" class="whitespace-pre-wrap break-words">{{item.outcome_remarks}}</p></article><p v-if="!detail.actions.length" class="ui-muted mt-3">No follow-up actions recorded.</p></section></section>
     <section v-else class="space-y-4"><section class="ui-panel p-4"><h3 class="ui-section-title">Independent review</h3><p class="ui-muted mt-2">The author submits the record. Another authorized reviewer returns it or finalizes it. Final records are preserved; corrections use a linked addendum.</p><p v-if="record.review_comments" class="mt-3 whitespace-pre-wrap break-words rounded border border-amber-300 bg-kalinga-warm p-3 text-sm text-amber-950">Review comments: {{record.review_comments}}</p><label v-if="permitted('return_for_revision')" class="mt-4 block text-sm font-medium">Reviewer comments<textarea :value="String(reviewForm.comments??'')" @input="reviewForm.comments=($event.target as HTMLTextAreaElement).value" maxlength="5000" rows="3" class="ui-field mt-1" :disabled="disabled"/></label><div class="mt-4 flex flex-wrap gap-3"><button v-if="permitted('mark_scheduled')" class="ui-button" :disabled="disabled" @click="transition('scheduled')">Mark scheduled</button><button v-if="permitted('start')" class="ui-button" :disabled="disabled" @click="transition('in_progress')">Start conference</button><button v-if="permitted('submit_for_review')" class="ui-button-primary" :disabled="disabled" @click="transition('for_review')">Submit for review</button><button v-if="permitted('return_for_revision')" class="ui-button" :disabled="disabled" @click="transition('returned_for_revision')">Return for revision</button><button v-if="permitted('finalize')" class="ui-button-primary" :disabled="disabled" @click="transition('final')">Finalize conference</button></div><p v-if="record.finalized_at" class="mt-3 text-sm text-slate-700">Finalized {{philippineTimestamp(record.finalized_at)}}</p></section><PlanningForm v-if="permitted('reschedule')" id="conference-reschedule" v-model="rescheduleForm" title="Reschedule conference" description="Save discussion and other entries first. Preserve the prior schedule and documented reason in history." :fields="rescheduleFields" :busy="disabled" :errors="errorsFor('reschedule')" submit-label="Save new schedule" @submit="reschedule"/><PlanningForm v-if="permitted('addendum')" id="conference-addendum" v-model="addendumForm" title="Create linked addendum" description="The original final record remains unchanged. The addendum follows its own draft and review workflow." :fields="addendumFields" :busy="disabled" :errors="errorsFor('addendum')" submit-label="Create addendum" @submit="addendum"/><section class="ui-panel overflow-hidden"><header class="ui-panel-header bg-brand-50"><h3 class="ui-section-title">Conference history</h3></header><ol class="divide-y divide-slate-200"><li v-for="item in detail.history" :key="item.id" class="space-y-2 p-4 text-sm"><p class="font-semibold">{{human(item.event)}}</p><p class="text-xs text-slate-600">{{item.actor_name||'Recorded actor unavailable'}} - {{human(item.actor_role)}} - {{philippineTimestamp(item.created_at)}}</p><p v-if="item.comments" class="whitespace-pre-wrap break-words">{{item.comments}}</p><p v-if="item.new_scheduled_at" class="text-xs leading-5 text-slate-700">Prior schedule: {{philippineTimestamp(item.prior_scheduled_at)}}<br>New schedule: {{philippineTimestamp(item.new_scheduled_at)}}</p></li></ol><p v-if="!detail.history.length" class="ui-muted p-4">No history entries recorded.</p></section></section>
    </article><p v-else class="ui-panel p-4 text-sm text-slate-600">Use Refresh to load the selected authorized conference.</p>
   </div>
  </div>
 </section></AuthenticatedLayout>
</template>
